"Смены — это рабочее время основного магазина сотрудника (можно изменить). Ночные часы = часть смены между 22:00 и 06:00. Работа в два рабочих времени: «ещё одна смена» и разделение дней. Ввод заменяет позиции работы ниже; оплачиваемые отсутствия остаются. Когда смены ведутся в программе, вместо этого используется «🕘 Часы из смен».",
