"Ставки установлены согласно нормам, действующим в 2026 г. («Европа сейчас» 1 и 2): взносы работника PIO 10 % + безработица 0,5 %; работодатель 0,5 % + Фонд труда 0,2 %; налог 0/9/15 % (пороги 700 и 1.000 EUR, предельно); надбавка к налогу — за счёт работодателя (в брутто и в IOPPD не входит). При изменении норм число меняется здесь: уже рассчитанные сотрудники сохраняют записанные суммы, а новый расчёт (и «Рассчитать все» в открытом месяце) считает по новой ставке. Средняя зарплата для взноса за лиц с инвалидностью вносится отдельно за каждый расчётный год (среднее за предыдущий год). Строка нового года открывается автоматически с суммой прошлого года, которая исправляется после публикации нового среднего.",
