"Товар, найденный на объекте, когда компания начинает работу в программе (или у года нет истории): количество, закупочная цена без НДС, розничная цена с НДС и ставка НДС по товару, на дату (чаще всего 01.01. или день начала работы). Ввод вручную, сканером или импортом складской ведомости из другой программы (Excel/CSV). Закрытые начальные остатки — это инвентаризация всего объекта: строка «Начальные остатки» в торговой книге, остатки и цены в складских остатках, запасы и PD. У объекта одни начальные остатки.",
